use std::collections::HashMap;use crate::{ast::{Expr,Op,Stmt,Value},lexer::Span};
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum VelaRiType{Number,Boolean,String,Null}
#[derive(Debug,Clone,PartialEq)]pub struct SemanticError{pub message:String,pub span:Span}
pub struct SemanticAnalyzer{symbols:HashMap<String,VelaRiType>}
impl SemanticAnalyzer{pub fn new()->Self{Self{symbols:HashMap::new()}}pub fn analyze(&mut self,root:&Stmt)->Result<(),Vec<SemanticError>>{let mut e=Vec::new();self.stmt(root,&mut e);if e.is_empty(){Ok(())}else{Err(e)}}fn stmt(&mut self,s:&Stmt,e:&mut Vec<SemanticError>){match s{Stmt::Block(xs)=>for x in xs{self.stmt(x,e)},Stmt::Let{name,value,span}=>{if let Ok(t)=self.expr(value,e){if let Some(old)=self.symbols.insert(name.clone(),t){if old!=t{e.push(SemanticError{message:format!("variable `{name}` changed from {old:?} to {t:?}"),span:*span})}}}},Stmt::Print(x)=>{let _ = self.expr(x,e);},Stmt::Conditional{condition,then_branch,otherwise_branch,..}=>{if self.expr(condition,e)!=Ok(VelaRiType::Boolean){e.push(SemanticError{message:"if condition must be Boolean".into(),span:condition.span()})}for x in then_branch{self.stmt(x,e)}if let Some(xs)=otherwise_branch{for x in xs{self.stmt(x,e)}}},Stmt::RepeatLoop{iterations,body,..}=>{if self.expr(iterations,e)!=Ok(VelaRiType::Number){e.push(SemanticError{message:"repeat count must be Number".into(),span:iterations.span()})}for x in body{self.stmt(x,e)}},Stmt::CreateWindow{width,height,..}=>{for x in [width,height]{if self.expr(x,e)!=Ok(VelaRiType::Number){e.push(SemanticError{message:"window dimensions must be Number".into(),span:x.span()})}}}}}fn expr(&self,x:&Expr,e:&mut Vec<SemanticError>)->Result<VelaRiType,()>{match x{Expr::Literal(v,_)=>Ok(match v{Value::Number(_)=>VelaRiType::Number,Value::Boolean(_)=>VelaRiType::Boolean,Value::String(_)=>VelaRiType::String,Value::Null=>VelaRiType::Null}),Expr::Variable(n,sp)=>self.symbols.get(n).copied().ok_or_else(||{e.push(SemanticError{message:format!("variable `{n}` used before initialization"),span:*sp});()}),Expr::Unary{op,expr,span}=>{let t=self.expr(expr,e).map_err(|_|())?;if *op==Op::Neg&&t==VelaRiType::Number{Ok(t)}else{e.push(SemanticError{message:"unary minus requires Number".into(),span:*span});Err(())}},Expr::Binary{left,op,right,span}=>{let a=self.expr(left,e).map_err(|_|())?;let b=self.expr(right,e).map_err(|_|())?;match op{Op::Add|Op::Sub|Op::Mul|Op::Div if a==VelaRiType::Number&&b==a=>Ok(a),Op::Add if a==VelaRiType::String&&b==a=>Ok(a),Op::Eq if a==b=>Ok(VelaRiType::Boolean),Op::And|Op::Or if a==VelaRiType::Boolean&&b==a=>Ok(VelaRiType::Boolean),_=>{e.push(SemanticError{message:format!("invalid operation {op:?} for {a:?} and {b:?}"),span:*span});Err(())}}}}}}
